sp_widget.client_script:
api.controller = function($scope) {
    var c = this;

    c.ajustar = function(pacoteId) {
        var novoTotal = window.prompt('Novo total de sessões:');
        if (!novoTotal) { return; }
        c.erro = null;
        c.data.action = 'ajustar';
        c.data.pacoteId = pacoteId;
        c.data.novoTotal = novoTotal;
        c.server.update().then(function(r) {
            if (r.data.erro) { c.erro = r.data.erro; }
        });
    };
};

sp_widget.script:
(function() {
    var clienteId = options.cliente_id || (input && input.clienteId);

    if (input && input.action === 'ajustar') {
        if (!gs.hasRole('x_espaco.gestor') && !gs.hasRole('x_espaco.admin')) {
            data.erro = 'Sem permissão para ajustar pacotes.';
        } else {
            var pacote = new GlideRecord('x_espaco_pacote');
            if (pacote.get(input.pacoteId)) {
                pacote.setValue('total_sessoes', input.novoTotal);
                pacote.update();
            }
        }
    }

    data.pacotes = new GerenciarPacoteUseCase().listarPorCliente(clienteId);
})();
